# pokok baru: id, judul, uraian, wajib, dasar, keadaan
def _pokok(id_, judul, uraian, dasar, keadaan=None, wajib=False):
    d = dict(id=id_, judul=judul, uraian=uraian, dasarHukum=dasar, wajib=wajib)
    if keadaan:
        d['keadaan'] = keadaan
    return d


